/* ---------- Model picker ---------- */
/* a trigger that names the model and how hard it thinks, over the open list: speed, quality and cost as five-step meters
   with the real numbers on hover, and the thinking effort under them as a small dropdown */
.mpk{position:relative;display:flex;flex-direction:column;gap:var(--dm-s-2);width:100%;max-width:420px;margin:0 auto}
.mpk-top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px}
.mpk-lb{font-size:12.5px}
.mpk-tr{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 10px 0 6px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:13px;font-weight:500;white-space:nowrap;transition:box-shadow .16s}
@media (hover:hover) and (pointer:fine){.mpk-tr:hover{box-shadow:var(--dm-shadow-pop)}}
.mpk-tr>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.mpk-tr[aria-expanded="true"]>svg{transform:rotate(180deg)}
.mpk-tr:focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px}
.mpk-ef{font-weight:400;font-size:12.5px}
/* each model's mark carries the letter colour that reads on it (--dm-mt): on the accent fill that is --dm-on-accent */
.mpk-mk{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;font-size:11px;font-weight:500;color:var(--dm-mt,var(--dm-on-ink));background:var(--dm-mc,var(--dm-fg2));flex:none;transition:background .32s}
.mpk-p{padding:6px;display:flex;flex-direction:column}
.mpk-hd,.mpk-o{display:grid;grid-template-columns:20px minmax(0,1fr) repeat(3,34px);align-items:center;gap:10px}
.mpk-hd{padding:var(--dm-s-1) 10px 2px;font-size:11px;color:var(--dm-muted)}
.mpk-hd span{text-align:center}
.mpk-o{width:100%;padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-in);text-align:left;font-size:13px;transition:background .16s}
@media (hover:hover) and (pointer:fine){.mpk-o:hover{background:var(--dm-row)}}
.mpk-o[aria-checked="true"]{background:var(--dm-sel)}
.mpk-o[aria-checked="true"] .d{color:var(--dm-fg2)}
.mpk-o:focus-visible{outline:2px solid var(--dm-focus);outline-offset:-2px}
.mpk-o .t{display:flex;flex-direction:column;min-width:0}
.mpk-o .t b{font-weight:500;display:flex;align-items:center;gap:6px}
.mpk-o .ck{display:grid;color:var(--dm-accent-fg,var(--dm-accent));opacity:0;transform:scale(.6);transition:opacity .16s,transform .32s var(--dm-ease)}
.mpk-o[aria-checked="true"] .ck,.mpk-o .ck:has(.spin){opacity:1;transform:none}
.mpk-o .ck .spin{width:10px;height:10px;color:var(--dm-muted)}
.mpk-o .d{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mpk-o.busy .d{color:var(--dm-warn)}
.mpk-o.busy .mpk-mk{background:var(--dm-warn-mark);color:var(--dm-on-ink)}
.mpk-m{display:flex;gap:2px;height:8px}
.mpk-m i{flex:1;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);transition:background .32s}
.mpk-m i.on{background:var(--dm-fg2)}
.mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on{background:var(--dm-accent-mark,var(--dm-accent))}
/* the way out when a model can't take the request: wait for it, or a close match that starts now */
.mpk-sg{margin:var(--dm-s-1) var(--dm-s-1) 2px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-warn-bg);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.mpk-sgt{margin:0;font-size:12.5px;line-height:1.45}
.mpk-sga{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}
/* on the amber notice the secondary button is white, not grey */
.mpk-sg .pill.ghost{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.mpk-sg .pill.ghost:hover{box-shadow:var(--dm-shadow-pop)}}
.mpk-th{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--dm-s-2) var(--dm-s-3);padding:var(--dm-s-3) 10px 6px;margin:6px var(--dm-s-1) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.mpk-thh{display:flex;flex-direction:column;min-width:0;font-size:13px}
.mpk-thh b{font-weight:500;display:flex;align-items:center;gap:6px}
.mpk-thh b svg{color:var(--dm-muted)}
.mpk-thd{font-size:12px}
.mpk-eb{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:13px;transition:background .16s}
.mpk-eb[aria-expanded="true"]{background:var(--dm-hover)}
@media (hover:hover) and (pointer:fine){.mpk-eb:hover{background:var(--dm-hover)}}
.mpk-eb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.mpk-eb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.mpk-pop{min-width:220px}
.mpk-note{margin:0;padding:0 2px;font-size:12.5px;min-height:20px;display:flex;align-items:center;gap:6px}
.mpk-note svg{color:var(--dm-ok);flex:none}
/* phones: the line under each name wraps, and the meters keep room for their labels */
/* on a phone the meters close up so a model's line keeps two or three words to a row */
@media (max-width:480px){.mpk-hd,.mpk-o{grid-template-columns:20px minmax(0,1fr) repeat(3,34px);gap:6px}.mpk-hd{font-size:10.5px;padding-inline:6px}.mpk-o{padding-inline:6px}.mpk-o .d{white-space:normal}}
/* Clean (owner, 18 Nov): one measure inside the popover. Its content sits 16px in from each edge: the column heads, each
   row's mark and meters (the rows sit 8px in, with 8px of their own) and the foot's text. The picked row's fill is
   concentric with the popover's corners (22px = its 14px + the 8px inset), and the foot strip's select sits 8px from the
   right and bottom edges, a 28px pill (14 + 8 = 22). Selection is neutral: a grey row fill, an ink check, meters one step
   darker; the models' marks keep their own colours. The trigger is a secondary pill, and the popover scales and fades in
   from it */
:root[data-style="clean"] .mpk-tr,:root [data-style="clean"] .mpk-tr,:root [data-style="clean"].mpk-tr{gap:8px;padding:0 10px 0 6px;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease),transform var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .mpk-tr:hover,:root [data-style="clean"] .mpk-tr:hover,:root [data-style="clean"].mpk-tr:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .mpk-tr:active,:root [data-style="clean"] .mpk-tr:active,:root [data-style="clean"].mpk-tr:active{transform:scale(.97);box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .mpk-tr>svg,:root [data-style="clean"] .mpk-tr>svg,:root [data-style="clean"].mpk-tr>svg{transition:transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .mpk-p.panel,:root [data-style="clean"] .mpk-p.panel,:root [data-style="clean"].mpk-p.panel{padding:0;transform-origin:top right;transition:opacity var(--dm-t) var(--dm-ease),transform .32s var(--dm-ease)}
:root[data-style="clean"] .mpk-fold.shut .mpk-p,:root [data-style="clean"] .mpk-fold.shut .mpk-p,:root [data-style="clean"].mpk-fold.shut .mpk-p{opacity:0;transform:translateY(-4px) scale(.96)}
:root[data-style="clean"] :is(.mpk-hd,.mpk-o),:root [data-style="clean"] :is(.mpk-hd,.mpk-o),:root [data-style="clean"]:is(.mpk-hd,.mpk-o){grid-template-columns:20px minmax(0,1fr) repeat(3,40px);gap:10px}
:root[data-style="clean"] .mpk-hd,:root [data-style="clean"] .mpk-hd,:root [data-style="clean"].mpk-hd{padding:16px 16px 4px;line-height:16px}
:root[data-style="clean"] .mpk-list,:root [data-style="clean"] .mpk-list,:root [data-style="clean"].mpk-list{padding:0 8px 8px}
:root[data-style="clean"] .mpk-o,:root [data-style="clean"] .mpk-o,:root [data-style="clean"].mpk-o{padding:8px;border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .mpk-o[aria-checked="true"],:root [data-style="clean"] .mpk-o[aria-checked="true"],:root [data-style="clean"].mpk-o[aria-checked="true"]{background:var(--dm-chip)}
:root[data-style="clean"] .mpk-o[aria-checked="true"] .t b,:root [data-style="clean"] .mpk-o[aria-checked="true"] .t b,:root [data-style="clean"].mpk-o[aria-checked="true"] .t b{color:var(--dm-fg)}
:root[data-style="clean"] .mpk-mk,:root [data-style="clean"] .mpk-mk,:root [data-style="clean"].mpk-mk{border-radius:50%}
/* the check is ink and draws itself in when its row is picked */
:root[data-style="clean"] .mpk-o .ck,:root [data-style="clean"] .mpk-o .ck,:root [data-style="clean"].mpk-o .ck{color:var(--dm-fg);opacity:1;transform:none}
:root[data-style="clean"] .mpk-o .ck svg,:root [data-style="clean"] .mpk-o .ck svg,:root [data-style="clean"].mpk-o .ck svg{stroke-dasharray:22;stroke-dashoffset:22;transition:stroke-dashoffset .1s var(--dm-ease)}
:root[data-style="clean"] .mpk-o[aria-checked="true"] .ck svg,:root [data-style="clean"] .mpk-o[aria-checked="true"] .ck svg,:root [data-style="clean"].mpk-o[aria-checked="true"] .ck svg{stroke-dashoffset:0;transition:stroke-dashoffset .42s var(--dm-ease) .06s}
/* meters: ink pips on a faint grey track, one step darker on the picked row. As the popover opens they fill left to right,
   row by row */
@keyframes mpkpip{from{background-color:var(--dm-rail)}}
:root[data-style="clean"] .mpk-m,:root [data-style="clean"] .mpk-m,:root [data-style="clean"].mpk-m{gap:2px}
:root[data-style="clean"] .mpk-m i,:root [data-style="clean"] .mpk-m i,:root [data-style="clean"].mpk-m i{background:var(--dm-rail);transition:background-color .32s var(--dm-ease)}
:root[data-style="clean"] .mpk-m i.on,:root [data-style="clean"] .mpk-m i.on,:root [data-style="clean"].mpk-m i.on{background:var(--dm-fg2)}
:root[data-style="clean"] .mpk-o[aria-checked="true"] .mpk-m i:not(.on),:root [data-style="clean"] .mpk-o[aria-checked="true"] .mpk-m i:not(.on),:root [data-style="clean"].mpk-o[aria-checked="true"] .mpk-m i:not(.on){background:var(--dm-faint)}
:root[data-style="clean"] .mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on,:root [data-style="clean"] .mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on,:root [data-style="clean"].mpk-o[aria-checked="true"]:not(.busy) .mpk-m i.on{background:var(--dm-fg)}
:root[data-style="clean"] .mpk-fold:not(.shut) .mpk-m i.on,:root [data-style="clean"] .mpk-fold:not(.shut) .mpk-m i.on,:root [data-style="clean"].mpk-fold:not(.shut) .mpk-m i.on{animation:mpkpip .36s var(--dm-ease) backwards;animation-delay:calc(140ms + var(--dm-mpr,0) * 70ms + var(--dm-mpm,0) * 110ms + var(--dm-mpi,0) * 35ms)}
:root[data-style="clean"] .mpk-o:nth-child(2),:root [data-style="clean"] .mpk-o:nth-child(2),:root [data-style="clean"].mpk-o:nth-child(2){--dm-mpr:1}
:root[data-style="clean"] .mpk-o:nth-child(3),:root [data-style="clean"] .mpk-o:nth-child(3),:root [data-style="clean"].mpk-o:nth-child(3){--dm-mpr:2}
:root[data-style="clean"] .mpk-o:nth-child(n+4),:root [data-style="clean"] .mpk-o:nth-child(n+4),:root [data-style="clean"].mpk-o:nth-child(n+4){--dm-mpr:3}
:root[data-style="clean"] .mpk-m:nth-child(4),:root [data-style="clean"] .mpk-m:nth-child(4),:root [data-style="clean"].mpk-m:nth-child(4){--dm-mpm:1}
:root[data-style="clean"] .mpk-m:nth-child(5),:root [data-style="clean"] .mpk-m:nth-child(5),:root [data-style="clean"].mpk-m:nth-child(5){--dm-mpm:2}
:root[data-style="clean"] .mpk-m i:nth-child(2),:root [data-style="clean"] .mpk-m i:nth-child(2),:root [data-style="clean"].mpk-m i:nth-child(2){--dm-mpi:1}
:root[data-style="clean"] .mpk-m i:nth-child(3),:root [data-style="clean"] .mpk-m i:nth-child(3),:root [data-style="clean"].mpk-m i:nth-child(3){--dm-mpi:2}
:root[data-style="clean"] .mpk-m i:nth-child(4),:root [data-style="clean"] .mpk-m i:nth-child(4),:root [data-style="clean"].mpk-m i:nth-child(4){--dm-mpi:3}
:root[data-style="clean"] .mpk-m i:nth-child(5),:root [data-style="clean"] .mpk-m i:nth-child(5),:root [data-style="clean"].mpk-m i:nth-child(5){--dm-mpi:4}
/* the way out when a model is busy: its own section under the rows, between hairlines, with its buttons 16px in */
:root[data-style="clean"] .mpk-sg,:root [data-style="clean"] .mpk-sg,:root [data-style="clean"].mpk-sg{margin:0;padding:16px;border-radius:0;background:none;border-top:1px solid var(--dm-line);gap:12px}
