:root[data-style="clean"] .mpk-sga,:root [data-style="clean"] .mpk-sga,:root [data-style="clean"].mpk-sga{gap:8px}
:root[data-style="clean"] .mpk-sg .pill.ghost,:root [data-style="clean"] .mpk-sg .pill.ghost,:root [data-style="clean"].mpk-sg .pill.ghost{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .mpk-sg .pill.ghost:hover,:root [data-style="clean"] .mpk-sg .pill.ghost:hover,:root [data-style="clean"].mpk-sg .pill.ghost:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
