/* the foot strip: thinking on one line, 16px in, and its select a secondary pill 8px from the corner */
:root[data-style="clean"] .mpk-th,:root [data-style="clean"] .mpk-th,:root [data-style="clean"].mpk-th{flex-wrap:nowrap;gap:12px;margin:0;padding:8px 8px 8px 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .mpk-thh,:root [data-style="clean"] .mpk-thh,:root [data-style="clean"].mpk-thh{flex-direction:row;align-items:baseline;gap:8px;min-width:0;white-space:nowrap}
:root[data-style="clean"] .mpk-thh b,:root [data-style="clean"] .mpk-thh b,:root [data-style="clean"].mpk-thh b{flex:none;align-self:center}
