@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.mpk-eb:hover,.mpk-eb[aria-expanded="true"]),:root [data-style="clean"] :is(.mpk-eb:hover,.mpk-eb[aria-expanded="true"]),:root [data-style="clean"]:is(.mpk-eb:hover,.mpk-eb[aria-expanded="true"]){background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
