:root[data-style="clean"] .mpk-note svg,:root [data-style="clean"] .mpk-note svg,:root [data-style="clean"].mpk-note svg{color:var(--dm-ok-mark)}
/* phones: the thinking line goes under its label rather than being cut, and the select turns into a text control aligned by
   its text, its chevron 16px from the edge like the meters above it */
@media (max-width:480px){:root[data-style="clean"] :is(.mpk-hd,.mpk-o),:root [data-style="clean"] :is(.mpk-hd,.mpk-o),:root [data-style="clean"]:is(.mpk-hd,.mpk-o){grid-template-columns:20px minmax(0,1fr) repeat(3,36px);gap:8px}:root[data-style="clean"] .mpk-hd,:root [data-style="clean"] .mpk-hd,:root [data-style="clean"].mpk-hd{padding-inline:16px}:root[data-style="clean"] .mpk-o,:root [data-style="clean"] .mpk-o,:root [data-style="clean"].mpk-o{padding-inline:8px}
  :root[data-style="clean"] .mpk-th,:root [data-style="clean"] .mpk-th,:root [data-style="clean"].mpk-th{padding:12px 16px}:root[data-style="clean"] .mpk-thh,:root [data-style="clean"] .mpk-thh,:root [data-style="clean"].mpk-thh{flex-direction:column;align-items:flex-start;gap:0;white-space:normal}:root[data-style="clean"] .mpk-thh b,:root [data-style="clean"] .mpk-thh b,:root [data-style="clean"].mpk-thh b{align-self:auto}
  :root[data-style="clean"] .mpk-eb,:root [data-style="clean"] .mpk-eb,:root [data-style="clean"].mpk-eb{margin-right:-10px;background:none;box-shadow:none}
